        let config: Self = rust_yaml::from_str(&read_to_string(path)?)?;
        anyhow::ensure!(
            config.candidate_budget > 0,
            "candidate_budget must be positive"
        );
        anyhow::ensure!(
            !config.resolution_python.as_os_str().is_empty(),
            "resolution_python must be configured"
        );
        Ok(config)
    }
}
